async function load(path){const r=await fetch(path);if(!r.ok)throw new Error(`无法读取 Token 数据（${r.status}）`);return r.json()}function flatten(o,p=[],out=[]){if(!o||typeof o!=='object')return out;if('$value'in o){out.push({path:p.join('.'),parts:p,type:o.$type||'unknown',value:o.$value,desc:o.$description||'',code:o.$extensions?.['com.figma.codeSyntax']?.WEB||'',id:o.$extensions?.['com.figma.variableId']||''});return out}Object.entries(o).forEach(([k,v])=>flatten(v,p.concat(k),out));return out}
