function compactSearchText(value){return String(value||'').toLowerCase().replace(/[\s._\-/]+/g,'')}
function fuzzyScore(value,query){const text=compactSearchText(value),needle=compactSearchText(query);if(!needle||!text)return Infinity;if(text===needle)return 0;if(text.startsWith(needle))return 5+text.length-needle.length;const included=text.indexOf(needle);if(included>=0)return 20+included;let cursor=0,gaps=0,last=-1;for(const char of needle){const index=text.indexOf(char,cursor);if(index<0)return Infinity;if(last>=0)gaps+=index-last-1;last=index;cursor=index+1}return 80+gaps+text.length-needle.length}
function searchViewForToken(token,lineageModel){if(lineageModel.byPath.has(token.path))return 'lineage';return Object.entries(CATEGORY_VIEWS).find(([,config])=>token.path===config.root||token.path.startsWith(`${config.root}.`))?.[0]||null}
function searchCandidates(query){if(!state.data||!state.modeData)return [];const lineageModel=buildLineageModel(),seen=new Set(),items=[],add=(token,view,raw=false)=>{if(!view||hidden(token))return;const key=`${view}\u0000${token.path}`;if(seen.has(key))return;seen.add(key);const name=raw?`${token.parts.at(-2)}-${label(token)}`:label(token),fields=[name,token.path,token.desc,token.doc,token.explain?.text,val(token)],scores=fields.map((field,index)=>fuzzyScore(field,query)+(index?index*8:0)),score=Math.min(...scores);if(Number.isFinite(score))items.push({token,view,name,score})};state.data.list.forEach(token=>add(token,searchViewForToken(token,lineageModel)));lineageModel.raw.forEach(token=>add(token,'lineage',true));return items.sort((a,b)=>a.score-b.score||a.name.localeCompare(b.name,'zh-CN')).slice(0,12)}
function searchViewTitle(view){return view==='lineage'?'颜色':CATEGORY_VIEWS[view]?.title||view}
function showSearchResults(query){const results=document.querySelector('#search-results'),text=query.trim();if(!results||!text){closeSearchResults();return}const items=searchCandidates(text);results.innerHTML=items.length?items.map(item=>`<button class="search-result" type="button" role="option" data-search-path="${encodeURIComponent(item.token.path)}" data-search-view="${item.view}"><span class="search-result-name">${escape(item.name)}</span><span class="search-result-meta"><span class="search-result-path">${escape(item.token.parts.slice(0,-1).join(' / '))}</span><span>${escape(searchViewTitle(item.view))}</span></span></button>`).join(''):'<div class="search-empty">没有匹配的 Token</div>';results.hidden=false;results.querySelectorAll('[data-search-path]').forEach(button=>button.onclick=()=>activateSearchResult(decodeURIComponent(button.dataset.searchPath),button.dataset.searchView))}
