function buildLineageModel(){const product=state.data,mode=state.modeData,modeRoot=MODE_ROOT[state.product];const raw=mode.list.filter(x=>x.type==='color'&&x.path.startsWith(`${modeRoot}.`));const business=product.list.filter(x=>x.type==='color'&&x.path.startsWith('🔵颜色.业务色版.业务色版.')&&!hidden(x));const semantic=product.list.filter(x=>x.type==='color'&&SEMANTIC_ROOTS.includes(x.parts[1])&&!hidden(x));const foundation=product.list.filter(x=>x.type==='color'&&x.parts[1]==='基础色板'&&!hidden(x));const nodes=[...raw,...business,...semantic,...foundation];const byPath=new Map(nodes.map(x=>[x.path,x])),edges=[];business.forEach(x=>{const source=foundationReferenceForBusiness(x,foundation)||(x.isAlias&&byPath.has(x.ref)?x.ref:rawReferenceForBusiness(x,raw));if(source)edges.push({source,target:x.path})});foundation.forEach(x=>{const source=rawReferenceForFoundation(x,raw);if(source)edges.push({source,target:x.path})});semantic.forEach(x=>{if(x.isAlias&&byPath.has(x.ref))edges.push({source:x.ref,target:x.path})});return {raw,business,semantic,foundation,nodes,byPath,edges}}
