function renderLineage(all,g){const map=state.data.map;const isGroup=Boolean(state.group);let chosen=state.selected&&g.connected.has(state.selected)?state.selected:(g.leaves[0]||g.roots[0]);const cols=isGroup?groupChains(state.group,all,g,map):(chosen?chain(chosen,g,map):[]);const colors=state.data.list.filter(x=>x.type==='color'&&!hidden(x));const tree=makeTree(colors);const detail=isGroup?`<h2>${escape(state.group.split('.').at(-1))}</h2><span class="chip">父分组</span><dl><dt>血缘 Token 数量</dt><dd>${all.filter(x=>x.path.startsWith(`${state.group}.`)&&g.connected.has(x.path)).length}</dd><dt>展示方式</dt><dd>已汇总展示该分组下所有具有血缘关系的 Token。</dd></dl>`:renderDetail(map.get(chosen));return `<div class="page"><div class="layout"><aside class="panel tree-panel"><div class="tree-heading"><div><h2>01 产品线</h2><p class="muted">颜色 · ${colors.length} 个 Token</p></div><button class="tree-toggle" data-tree-toggle aria-label="收起全部分组">☷<span class="tree-toggle-arrow">⌃</span></button></div><div class="token-tree">${treeHtml(tree)}</div></aside><section class="panel canvas"><div class="lineage-head"><div><h2>${isGroup?`${state.group.split('.').at(-1)} · 分组血缘`:`${state.product} · ${state.mode} 血缘关系`}</h2><div class="muted">左：终极父节点　右：引用它的分子节点</div></div><div class="legend"><span><i style="background:var(--orange)"></i>原始值</span><span><i style="background:var(--purple)"></i>引用</span><span><i style="background:var(--teal)"></i>叶子</span></div></div>${cols.length?`<div class="graph">${cols.map((col,i)=>`${i?'<div class="arrow">→</div>':''}<div class="graph-col">${col.map(p=>node(map.get(p),i===0?'root':(i===cols.length-1?'leaf':'alias'))).join('')}</div>`).join('')}</div>`:'<div class="empty">当前分组暂无可展示的引用血缘</div>'}</section><aside class="panel detail">${detail}</aside></div></div>`}
function tokenLineageHtml(x,map){const chain=[],seen=new Set();let current=x;while(current&&!seen.has(current.path)){seen.add(current.path);chain.unshift(current.path);if(!current.isAlias||!current.ref)break;const parent=map.get(current.ref);if(!parent){chain.unshift(current.ref);break}current=parent}return `<dt>Token 血缘</dt><dd class="detail-lineage-path" aria-label="Token 血缘"><div class="detail-path-row">${chain.map((path,index)=>{const token=map.get(path),name=token?label(token):path.split('.').at(-1);return `${index?'<i>→</i>':''}<span class="${path===x.path?'current':''}">${escape(name)}</span>`}).join('')}</div></dd>`}
function renderDetail(x){if(!x)return '<div class="empty">选择一个节点查看说明</div>';const info=x.explain||{},meaning=info.text||'当前 Token 尚未补充说明。',map=state.data.map,resolved=resolvedToken(x,map),currentValue=resolvedValue(x,map),color=resolved?.value?.hex?resolvedColor(x,map):'';return `<h2>${label(x)}</h2><span class="chip">${x.type}</span>${x.isAlias?'<span class="chip">引用 Token</span>':'<span class="chip">原始值</span>'}<dl>${tokenLineageHtml(x,map)}<dt>当前值</dt><dd class="value detail-current-value">${color?`<span class="color-dot" style="--token-color:${escape(color)}"></span>`:''}<code>${escape(currentValue)}</code></dd><dt>含义 / 使用场景</dt><dd>${escape(meaning)}</dd>${x.code?`<dt>CSS 变量</dt><dd class="value">${escape(x.code)}</dd>`:''}</dl>`}
function sizeGuide(){return `<section class="panel size-guide"><h2>尺寸 Token 的区别与使用场景</h2><p>根据间距发生的位置和使用主体选择 Token，避免仅按数值大小替换。</p><div class="size-guide-grid"><article class="size-guide-card"><h3>间距 <code>gap</code></h3><p><strong>元素之间的距离。</strong>基础组件与业务布局均可使用，例如图标与文字、按钮组、表单项或卡片之间的间隔。研发可对应 CSS 的 <code>gap</code> 或 <code>margin</code>。</p></article><article class="size-guide-card"><h3>布局边距 <code>paddingLayout</code></h3><p><strong>业务布局与容器边界之间的距离。</strong>主要用于页面、区块、卡片内容区等业务布局，表达统一的布局留白；业务侧需要容器内边距时优先使用。</p></article><article class="size-guide-card"><h3>内边距 <code>padding</code></h3><p><strong>基础组件内部内容与组件边界的距离。</strong>用于按钮、输入框、标签等组件内部，由组件规范统一控制；业务布局不建议直接调用，应优先选择 <code>paddingLayout</code> 或 <code>gap</code>。</p></article></div></section>`}
function shadowLayerColor(x){const hex=x.value?.hex||'#000000',alpha=Math.max(0,Math.min(1,Number(x.value?.alpha??1))),value=hex.replace('#',''),r=parseInt(value.slice(0,2),16),g=parseInt(value.slice(2,4),16),b=parseInt(value.slice(4,6),16);return `rgba(${r}, ${g}, ${b}, ${alpha.toFixed(2)})`}
function shadowLayerGeometry(name,count){if(name==='boxShadowSubtle')return ['0 1px 2px 0','0 2px 6px -1px'].slice(0,count);if(name==='boxShadowTertiary')return ['0 1px 2px 0','0 1px 6px -1px','0 2px 4px 0'].slice(0,count);return ['0 6px 16px 0','0 3px 6px -4px','0 9px 28px 8px'].slice(0,count)}
function boxShadowGroups(rows){const groups=new Map();rows.forEach(x=>{const path=x.parts.slice(0,-1).join('.'),name=x.parts.at(-2);if(!groups.has(path))groups.set(path,{path,name,layers:[]});groups.get(path).layers.push(x)});return [...groups.values()]}
function renderBoxShadowCategory(rows,config){const groups=boxShadowGroups(rows),chosen=groups.find(group=>state.selected===group.path||state.selected?.startsWith(`${group.path}.`))||groups[0];if(!chosen)return `<div class="page"><section class="panel empty">当前分类没有 Token</section></div>`;const geometries=shadowLayerGeometry(chosen.name,chosen.layers.length),shadows=chosen.layers.map((layer,index)=>`${geometries[index]} ${shadowLayerColor(layer)}`),description=state.kmsDocs.get(normalizeTokenName(chosen.name))||'由多层阴影颜色叠加构成，用于表达容器与基准面的层级关系。',meaning=[description,fdComponentUsageText(state.fdTokenUsage.get(chosen.path))].filter(Boolean).join(' ');return `<div class="page"><div class="layout category-layout shadow-category-layout"><aside class="panel tree-panel"><div class="tree-heading"><div><h2>${escape(config.title)}</h2><p class="muted">${groups.length} 个 Token</p></div></div><div class="shadow-group-list">${groups.map(group=>`<button class="shadow-group-item ${group.path===chosen.path?'selected':''}" data-token="${encodeURIComponent(group.path)}"><span>${escape(group.name)}</span><small>${group.layers.length} 层</small></button>`).join('')}</div></aside><aside class="panel detail shadow-detail"><h2>${escape(chosen.name)}</h2><span class="chip">组合盒子阴影</span><div class="shadow-preview-stage"><article class="shadow-preview-card" style="box-shadow:${escape(shadows.join(','))}"><strong>阴影预览</strong><span>${chosen.layers.length} 层颜色同时生效</span></article></div><dl><dt>含义 / 使用场景</dt><dd>${escape(meaning)}</dd><dt>阴影分层</dt><dd class="shadow-layer-list">${chosen.layers.map((layer,index)=>`<div><span class="color-dot" style="--token-color:${escape(resolvedColor(layer,state.data.map))}"></span><b>${escape(label(layer))}</b><code>${escape(geometries[index])} ${escape(val(layer))}</code></div>`).join('')}</dd><dt>CSS 预览值</dt><dd class="value shadow-css-value">box-shadow: ${escape(shadows.join(', '))};</dd></dl></aside></div></div>`}
function borderShadowDescription(name){return {controlShadow:'控制输入组件正常或聚焦状态下的外轮廓阴影。',controlWarningShadow:'控制输入组件警告状态下的外轮廓阴影。',controlErrorShadow:'控制输入组件错误状态下的外轮廓阴影。'}[name]||'由颜色和扩散半径共同构成的描边阴影。'}
function renderBorderShadowCategory(rows,config){const groups=boxShadowGroups(rows),chosen=groups.find(group=>state.selected===group.path||state.selected?.startsWith(`${group.path}.`))||groups[0];if(!chosen)return `<div class="page"><section class="panel empty">当前分类没有 Token</section></div>`;const map=state.data.map,colorToken=chosen.layers.find(layer=>label(layer).toLowerCase()==='color'),spreadToken=chosen.layers.find(layer=>label(layer).toLowerCase()==='spread'),resolvedColorToken=resolvedToken(colorToken,map),colorCss=resolvedColorToken?.value?.hex?shadowLayerColor(resolvedColorToken):'#000',colorValue=resolvedValue(colorToken,map),spreadValue=resolvedValue(spreadToken,map),spreadNumber=Number.parseFloat(spreadValue)||0,shadow=`0 0 0 ${spreadNumber}px ${colorCss}`,meaning=[borderShadowDescription(chosen.name),fdComponentUsageText(state.fdTokenUsage.get(chosen.path))].filter(Boolean).join(' ');return `<div class="page"><div class="layout category-layout shadow-category-layout"><aside class="panel tree-panel"><div class="tree-heading"><div><h2>${escape(config.title)}</h2><p class="muted">${groups.length} 个 Token</p></div></div><div class="shadow-group-list">${groups.map(group=>`<button class="shadow-group-item ${group.path===chosen.path?'selected':''}" data-token="${encodeURIComponent(group.path)}"><span>${escape(group.name)}</span><small>2 项参数</small></button>`).join('')}</div></aside><aside class="panel detail shadow-detail"><h2>${escape(chosen.name)}</h2><span class="chip">组合描边阴影</span><div class="shadow-preview-stage"><article class="shadow-preview-card border-shadow-preview-card" style="box-shadow:${escape(shadow)}"><strong>描边阴影预览</strong><span>Color + Spread 同时生效</span></article></div><dl><dt>含义 / 使用场景</dt><dd>${escape(meaning)}</dd><dt>阴影参数</dt><dd class="shadow-parameter-list"><div><span class="color-dot" style="--token-color:${escape(resolvedColor(colorToken,map))}"></span><b>Color</b><code>${escape(colorValue)}</code></div><div><span class="spread-symbol" aria-hidden="true">↔</span><b>Spread</b><code>${escape(spreadValue)}px</code></div></dd><dt>CSS 预览值</dt><dd class="value shadow-css-value">box-shadow: ${escape(shadow)};</dd></dl></aside></div></div>`}
function renderCategory(all,config){if(!config)return '<div class="page"><section class="panel empty">当前分类不存在</section></div>';const rows=all.filter(x=>(x.path===config.root||x.path.startsWith(`${config.root}.`))&&match(x));if(config.root==='🔵基础.盒子阴影')return renderBoxShadowCategory(rows,config);if(config.root==='🔵基础.描边阴影')return renderBorderShadowCategory(rows,config);const trimDepth=config.root.split('.').length,tree=makeTree(rows,trimDepth),chosen=rows.find(x=>x.path===state.selected)||rows[0],guide=config.root==='🔵尺寸'?sizeGuide():'';return `<div class="page">${guide}<div class="layout category-layout"><aside class="panel tree-panel"><div class="tree-heading"><div><h2>${escape(config.title)}</h2><p class="muted">${rows.length} 个 Token</p></div><button class="tree-toggle" data-tree-toggle aria-label="收起全部分组">☷<span class="tree-toggle-arrow">⌃</span></button></div><div class="token-tree">${treeHtml(tree)}</div></aside><aside class="panel detail">${renderDetail(chosen)}</aside></div></div>`}
function renderTokens(all){const rows=all.filter(x=>EXPLAIN_GROUPS.some(group=>x.path===group||x.path.startsWith(`${group}.`))&&match(x));const tree=makeTree(rows);const chosen=rows.find(x=>x.path===state.selected)||rows[0];const content=chosen?`<div class="token-summary"><span class="chip">${escape(chosen.type)}</span><h3>${escape(label(chosen))}</h3><div class="value large-value">${escape(val(chosen))}</div><h3>含义 / 使用场景</h3><p>${escape(chosen.explain?.text||'待补充说明')}</p></div>`:'<div class="explain-placeholder">没有匹配的 Token。</div>';return `<div class="page"><div class="layout"><aside class="panel tree-panel"><div class="tree-heading"><div><h2>01 产品线</h2><p class="muted">尺寸、字号、行高、描边尺寸、透明度</p></div><button class="tree-toggle" data-tree-toggle aria-label="收起全部分组">☷<span class="tree-toggle-arrow">⌃</span></button></div><div class="token-tree">${treeHtml(tree)}</div></aside><section class="panel explain-panel"><h2>Token 说明 · ${state.product}</h2><p class="muted">按 01 产品线原始树结构展示，没有血缘关系的全局数值 Token。</p>${content}</section><aside class="panel detail">${renderDetail(chosen)}</aside></div></div>`}
function renderCompare(all){return `<div class="page"><section class="panel"><h2>${state.product} · Light / Dark 对比</h2><p class="muted">用同一语义 Token 观察模式切换后的最终值。</p><div class="empty">切换顶部模式即可查看对应 Token 值；完整差异对比将在选定 Token 后展开。</div></section></div>`}
function renderQuality(all){const g=lineage(all),broken=all.filter(x=>x.broken),missing=all.filter(x=>!x.desc&&!x.doc),orphans=all.filter(x=>!g.connected.has(x.path));return `<div class="page"><section class="panel"><h2>数据治理</h2><p class="muted">用于讲解前检查数据完整性，不修改原始 Figma Token。</p><div class="quality-grid"><div class="quality-card"><span>缺少说明</span><b>${missing.length}</b><small>可结合文档补充</small></div><div class="quality-card"><span>断裂引用</span><b>${broken.length}</b><small>需回到 Figma 检查</small></div><div class="quality-card"><span>独立 Token</span><b>${orphans.length}</b><small>不进入血缘图</small></div></div><div class="doc-note">本期已排除：🔵颜色 / AI基础色、🔵颜色 / AI业务色板。</div></section></div>`}
